  $('#projectSaveTheme').onclick=()=>{const name=prompt('Nom du thème :','Mon thème');if(!name?.trim())return;const saved=readCollection(THEMES_KEY);saved.unshift({id:'th'+Date.now(),name:name.trim().slice(0,64),date:new Date().toLocaleDateString('fr-FR'),snapshot:structuredClone(profile)});saveCollection(THEMES_KEY,saved);$('#studioProjectMenu').open=false;};
  $('#liveDone').onclick=()=>toggleEdit(false);if(HOSTED){installAccountActions();$('#copyPublicLink').onclick=copyMyPublicLink;}
