function bindElementRailLive(){document.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>selectLiveElement(b.dataset.element));bindConnectionQuickDelete();document.querySelectorAll('[data-add-widget]').forEach(b=>b.onclick=()=>{remember();const type=b.dataset.addWidget,id='w'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);profile.widgets.push({id,type,name:type==='text'?'Nouveau texte':'Nouvelle image',text:type==='text'?'your little universe ♡':'',x:70,y:65,mobileX:50,mobileY:70,width:180,rotation:0,opacity:100,background:'#35243f',background2:'#e5abd2',gradient:false,noBubble:false,color:'#ffffff',color2:'#f0aedb',textGradient:false,borderRadius:18,animation:'none',hover:'none',linked:false,linkStyle:'curve',fileId:null});saveProfile();selectedElement=id;renderPage()})}

// Thèmes portables : profil + médias utilisés, sans toucher aux autres données du navigateur.
const PORTABLE_THEME_FORMAT='hushbun-studio-theme',PORTABLE_THEME_VERSION=1;
function portableMediaIds(p){
 const ids=new Set(Object.values(p.mediaRefs||{}));
 for(const w of p.widgets||[])if(w.fileId)ids.add(w.fileId);
 for(const t of p.playlist||[]){if(t.audioId)ids.add(t.audioId);if(t.coverId)ids.add(t.coverId)}
 return [...ids].filter(id=>typeof id==='string'&&id.length>0);
}
function blobAsDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||new Error('Lecture impossible'));reader.readAsDataURL(blob)})}
function dataUrlToBlob(data){const match=/^data:([^;,]*)(;base64)?,(.*)$/s.exec(data);if(!match||!match[2])throw new Error('Média encodé invalide');const raw=atob(match[3]);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:match[1]||'application/octet-stream'})}
async function exportPortableTheme(){
 const button=$('#exportTheme');if(button){button.disabled=true;button.textContent='Export en cours…'}
 try{
  saveProfile();const snapshot=structuredClone(profile),assets=[];
  for(const id of portableMediaIds(snapshot)){
   const file=await mediaGet(id);
   if(!(file instanceof Blob))throw new Error('Média manquant : '+id+'. Remets le fichier dans ta bibliothèque avant export.');
   assets.push({id,name:file.name||id,type:file.type||'application/octet-stream',data:await blobAsDataUrl(file)});
  }
  const portable={format:PORTABLE_THEME_FORMAT,version:PORTABLE_THEME_VERSION,createdAt:new Date().toISOString(),profile:snapshot,assets};
  const file=new Blob([JSON.stringify(portable)],{type:'application/json'}),url=URL.createObjectURL(file),link=document.createElement('a');
  link.href=url;link.download='hushbun-theme-'+cleanUsername(profile.username)+'-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  alert('Thème exporté avec '+assets.length+' média(s). Conserve ce fichier pour importer ton profil ailleurs.');
 }catch(err){console.error(err);alert('Export impossible : '+err.message)}finally{if(button){button.disabled=false;button.textContent='↓ Exporter mon thème'}}
}
async function importPortableTheme(file){
 try{
  const parsed=JSON.parse(await file.text());
  if(parsed?.format!==PORTABLE_THEME_FORMAT||parsed.version!==1||!parsed.profile||typeof parsed.profile!=='object'||Array.isArray(parsed.profile)||!Array.isArray(parsed.assets))throw new Error('Ce fichier n’est pas un export hushbun. Studio compatible.');
  if(!Array.isArray(parsed.profile.widgets)||!Array.isArray(parsed.profile.connections)||!Array.isArray(parsed.profile.groups))throw new Error('Profil incomplet.');
  const ids=portableMediaIds(parsed.profile);
  if(ids.some(id=>!parsed.assets.some(a=>a.id===id)))throw new Error('Le fichier ne contient pas tous les médias du thème.');
  if(!confirm('Importer ce thème ? Ton profil actuel sera remplacé. Exporte-le d’abord pour conserver une sauvegarde.'))return;
  const mapping=new Map(),prefix='library:import-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)+'-';
  for(let i=0;i<parsed.assets.length;i++){
   const asset=parsed.assets[i];if(typeof asset.id!=='string'||typeof asset.data!=='string'||!asset.data.startsWith('data:'))throw new Error('Média incorrect dans le fichier.');
   const newId=prefix+i;const blob=dataUrlToBlob(asset.data);await mediaSet(newId,new File([blob],String(asset.name||'media').slice(0,255),{type:blob.type}));mapping.set(asset.id,newId);
  }
  const next=structuredClone(parsed.profile);
  next.mediaRefs=Object.fromEntries(Object.entries(next.mediaRefs||{}).map(([k,id])=>[k,mapping.get(id)||id]));
  next.widgets.forEach(w=>{if(w.fileId)w.fileId=mapping.get(w.fileId)||w.fileId});
  (next.playlist||[]).forEach(t=>{if(t.audioId)t.audioId=mapping.get(t.audioId)||t.audioId;if(t.coverId)t.coverId=mapping.get(t.coverId)||t.coverId});
  remember();profile={...DEFAULT,...next};if(HOSTED&&studioUser)profile.username=studioUser.username;
  activeTrackIndex=0;saveProfile();await loadMedia();await loadWidgetMedia();renderPage();
  if(HOSTED){
    clearTimeout(cloudTimer);
    await cloudSave();
    const verification=await api('/api/my-profile');
    if(!verification.ok)throw new Error('Import local effectué mais confirmation de sauvegarde en ligne impossible.');
  }
  alert('Thème importé avec '+parsed.assets.length+' média(s). '+(HOSTED?'Sauvegarde en ligne confirmée.':'Sauvegarde locale effectuée.'));
 }catch(err){console.error(err);alert('Import impossible : '+err.message)}
}

// V0.6.4 : bibliothèque locale de thèmes et compositions.
const THEMES_KEY='hushbun-studio-themes-v64', CREATIONS_KEY='hushbun-studio-creations-v64';
function readCollection(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function saveCollection(key,data){localStorage.setItem(key,JSON.stringify(data))}
function themePanel(){const themes=readCollection(THEMES_KEY);return section('Mes thèmes','Chaque sauvegarde comprend le texte, les réglages, les widgets et les liaisons. Les fichiers médias restent dans cette bibliothèque locale.',`<button class="button highlight" id="saveTheme">+ Enregistrer le thème actuel</button>`+themes.map(t=>`<div class="hb-library-row"><b>${safe(t.name)}</b><small>${safe(t.date||'')}</small><div class="widget-actions"><button class="button muted" data-restore-theme="${safe(t.id)}">Restaurer</button><button class="button muted" data-delete-theme="${safe(t.id)}">Supprimer</button></div></div>`).join('')+(themes.length?'':'<p class="hint">Aucun thème sauvegardé.</p>'))}
function creationsPanel(){const packs=readCollection(CREATIONS_KEY);return section('Mes créations','Enregistre les widgets sélectionnés comme une composition réutilisable.',`<button class="button highlight" id="saveCreation">+ Enregistrer les widgets sélectionnés</button>`+packs.map(t=>`<div class="hb-library-row"><b>${safe(t.name)}</b><small>${t.widgets.length} widgets</small><div class="widget-actions"><button class="button muted" data-insert-creation="${safe(t.id)}">Insérer</button><button class="button muted" data-delete-creation="${safe(t.id)}">Supprimer</button></div></div>`).join('')+(packs.length?'':'<p class="hint">Aucune création enregistrée.</p>'))}
let chosenWidgets=new Set();
function layersPanel(){return section('Calques et groupes','En haut = devant. Verrouiller un élément empêche de le déplacer.',`<div class="widget-actions"><button class="button muted" id="groupSelected">Grouper la sélection</button><button class="button muted" id="ungroupSelected">Dissocier</button><button class="button muted" id="scaleGroupUp">Agrandir le groupe +10 %</button><button class="button muted" id="scaleGroupDown">Réduire le groupe −10 %</button></div>`+profile.widgets.slice().sort((a,b)=>(b.zIndex||10)-(a.zIndex||10)).map(w=>`<div class="hb-layer-row"><label><input type="checkbox" data-layer-choose="${safe(w.id)}" ${chosenWidgets.has(w.id)?'checked':''}/> ${safe(w.name)}</label><div class="widget-actions"><button data-layer-action="up" data-layer-id="${safe(w.id)}" title="Avancer">↑</button><button data-layer-action="down" data-layer-id="${safe(w.id)}" title="Reculer">↓</button><button data-layer-action="lock" data-layer-id="${safe(w.id)}">${w.locked?'Déverrouiller':'Verrouiller'}</button><button data-layer-action="visible" data-layer-id="${safe(w.id)}">${w.visible===false?'Afficher':'Masquer'}</button></div>${w.groupId?`<small>Groupe ${safe(w.groupId)}</small>`:''}</div>`).join(''))}
function wireCollections(root){
 root.querySelector('#saveTheme')?.addEventListener('click',()=>{const name=prompt('Nom du thème :','Mon thème');if(!name?.trim())return;const saved=readCollection(THEMES_KEY);saved.unshift({id:'th'+Date.now(),name:name.trim().slice(0,64),date:new Date().toLocaleDateString('fr-FR'),snapshot:structuredClone(profile)});saveCollection(THEMES_KEY,saved);renderControls()});
 root.querySelectorAll('[data-restore-theme]').forEach(b=>b.onclick=async()=>{const t=readCollection(THEMES_KEY).find(x=>x.id===b.dataset.restoreTheme);if(!t||!confirm('Restaurer ce thème ? Les modifications non enregistrées seront remplacées.'))return;remember();const preserved={...t.snapshot};profile={...DEFAULT,...preserved,widgets:structuredClone(preserved.widgets||[]),connections:structuredClone(preserved.connections||[]),groups:structuredClone(preserved.groups||[])};saveProfile();await loadMedia();await loadWidgetMedia();renderPage()});
 root.querySelectorAll('[data-delete-theme]').forEach(b=>b.onclick=()=>{if(!confirm('Supprimer cette sauvegarde ?'))return;saveCollection(THEMES_KEY,readCollection(THEMES_KEY).filter(x=>x.id!==b.dataset.deleteTheme));renderControls()});
 root.querySelectorAll('[data-layer-choose]').forEach(b=>b.onchange=()=>{b.checked?chosenWidgets.add(b.dataset.layerChoose):chosenWidgets.delete(b.dataset.layerChoose)});
 root.querySelectorAll('[data-layer-action]').forEach(b=>b.onclick=()=>{const w=profile.widgets.find(x=>x.id===b.dataset.layerId);if(!w)return;remember();if(b.dataset.layerAction==='up')w.zIndex=Math.min(99,(w.zIndex||10)+1);if(b.dataset.layerAction==='down')w.zIndex=Math.max(5,(w.zIndex||10)-1);if(b.dataset.layerAction==='lock')w.locked=!w.locked;if(b.dataset.layerAction==='visible')w.visible=w.visible===false;saveProfile();renderControls();renderPreview()});
 root.querySelector('#groupSelected')?.addEventListener('click',()=>{const ws=profile.widgets.filter(w=>chosenWidgets.has(w.id));if(ws.length<2){alert('Sélectionne au moins deux widgets.');return}remember();const id='grp'+Date.now();ws.forEach(w=>w.groupId=id);profile.groups.push({id,name:'Groupe '+(profile.groups.length+1)});saveProfile();renderControls()});
 root.querySelector('#ungroupSelected')?.addEventListener('click',()=>{remember();profile.widgets.filter(w=>chosenWidgets.has(w.id)).forEach(w=>delete w.groupId);saveProfile();renderControls()});
 for(const [id,scale] of [['scaleGroupUp',1.1],['scaleGroupDown',.9]])root.querySelector('#'+id)?.addEventListener('click',()=>{const ws=profile.widgets.filter(w=>chosenWidgets.has(w.id));if(ws.length<2){alert('Sélectionne au moins deux widgets.');return}remember();const cx=ws.reduce((n,w)=>n+w.x,0)/ws.length,cy=ws.reduce((n,w)=>n+w.y,0)/ws.length;const mx=ws.reduce((n,w)=>n+w.mobileX,0)/ws.length,my=ws.reduce((n,w)=>n+w.mobileY,0)/ws.length;ws.forEach(w=>{w.x=Math.max(3,Math.min(97,cx+(w.x-cx)*scale));w.y=Math.max(3,Math.min(97,cy+(w.y-cy)*scale));w.mobileX=Math.max(3,Math.min(97,mx+(w.mobileX-mx)*scale));w.mobileY=Math.max(3,Math.min(97,my+(w.mobileY-my)*scale));w.width=Math.max(40,Math.min(900,Math.round(w.width*scale)))});saveProfile();renderPreview();renderControls()});
 root.querySelector('#saveCreation')?.addEventListener('click',()=>{const ws=profile.widgets.filter(w=>chosenWidgets.has(w.id));if(!ws.length){alert('Sélectionne des widgets dans Calques et groupes.');return}const name=prompt('Nom de la création :','Ma composition');if(!name?.trim())return;const packs=readCollection(CREATIONS_KEY);packs.unshift({id:'cr'+Date.now(),name:name.trim().slice(0,64),widgets:structuredClone(ws)});saveCollection(CREATIONS_KEY,packs);renderControls()});
 root.querySelectorAll('[data-insert-creation]').forEach(b=>b.onclick=()=>{const p=readCollection(CREATIONS_KEY).find(x=>x.id===b.dataset.insertCreation);if(!p)return;remember();p.widgets.forEach((w,i)=>{const id='w'+Date.now()+i;profile.widgets.push({...structuredClone(w),id,name:w.name+' (copie)',x:Math.min(95,w.x+5),y:Math.min(95,w.y+5),groupId:null,fileId:w.fileId})});saveProfile();loadWidgetMedia();renderPage()});
 root.querySelectorAll('[data-delete-creation]').forEach(b=>b.onclick=()=>{if(!confirm('Supprimer cette création ?'))return;saveCollection(CREATIONS_KEY,readCollection(CREATIONS_KEY).filter(x=>x.id!==b.dataset.deleteCreation));renderControls()});
}
function bindWidgetActions(root){root.querySelectorAll('[data-widget-view]').forEach(el=>{el.addEventListener('click',()=>{const w=profile.widgets.find(x=>x.id===el.dataset.widgetView);if(!w||w.actionType!=='reveal')return;const div=el.querySelector('.widget-reveal');if(div)div.hidden=!div.hidden})})}
function setupCustomCursor(root){const el=root.querySelector('.hb-custom-cursor');if(!el||!matchMedia('(pointer:fine)').matches)return;root.classList.add('has-custom-cursor');const move=e=>{const r=root.getBoundingClientRect();el.style.left=(e.clientX-r.left-(Number(profile.cursorHotspotX)||0)/100*el.offsetWidth)+'px';el.style.top=(e.clientY-r.top-(Number(profile.cursorHotspotY)||0)/100*el.offsetHeight)+'px'};root.addEventListener('pointermove',move);root.addEventListener('pointerleave',()=>el.style.opacity='0');root.addEventListener('pointerenter',()=>el.style.opacity='1')}
window.addEventListener('resize',()=>requestAnimationFrame(()=>{const stage=document.querySelector('#liveStage')||document.querySelector('#preview')||document.querySelector('#publicView');if(stage){updateNoteGeometry(stage);drawWidgetLinks(stage)}}));if(HOSTED){bootHosted()}else{renderPage();loadMedia();loadWidgetMedia();}

// V0.6.9 — Authentification et profils publics Studio indépendants de la messagerie.
async function api(path,opts={}){
 try{const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const value=await r.json();return {ok:r.ok,status:r.status,...value}}
 catch(e){return {ok:false,error:'Impossible de joindre le serveur : '+e.message}}
}
function queueCloudSave(){if(!HOSTED||!studioUser||cloudHydrating)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(cloudSave,900)}
async function cloudSave(){if(!studioUser)return;if(cloudSaving){cloudPending=true;return}cloudSaving=true;
 const snapshot=structuredClone(profile);snapshot.username=studioUser.username;
 const reply=await api('/api/my-profile',{method:'PUT',body:JSON.stringify({profile:snapshot})});cloudSaving=false;
 const e=document.querySelector('#saveState');if(e)e.textContent=reply.ok?'✓ Sauvegardé en ligne':'⚠ Sauvegarde échouée';
 if(!reply.ok)console.warn('Sauvegarde:',reply.error);
 if(cloudPending){cloudPending=false;queueCloudSave()}
}
function blankProfile(username){return {...DEFAULT,username,displayName:username,bio:'',note:'',badgeText:'',musicTitle:'',musicArtist:'',entryEnabled:false,entryMusic:false,showViews:true,avatarRing:false,glow:false,widgets:[],connections:[],groups:[],playlist:[],mediaRefs:{}}}
function authScreen(mode='login',message=''){
 const register=mode==='register';history.replaceState({},'',register?'/register':'/');
 document.title='hushbun. Studio — '+(register?'Créer un compte':'Connexion');
 $('#app').innerHTML=`<main class="auth-page"><div class="auth-panel"><div class="auth-brand">♡ hushbun<span>.</span> <small>studio</small></div><p class="auth-subtitle">Crée ton univers. Partage ton profil.</p><div class="auth-tabs"><button id="authLogin" class="${!register?'active':''}">Se connecter</button><button id="authRegister" class="${register?'active':''}">Créer un compte</button></div><form id="authForm">${register?'<label>Pseudo unique<input required name="username" minlength="3" maxlength="24" pattern="[a-zA-Z0-9_-]+" autocomplete="username" placeholder="tonpseudo"></label>':''}<label>Adresse email<input required name="email" type="email" autocomplete="email" placeholder="toi@exemple.fr"></label><label>Mot de passe<input required name="password" type="password" minlength="${register?10:1}" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'10 caractères minimum':'Ton mot de passe'}"></label><p id="authError" role="alert" class="auth-error">${safe(message)}</p><button class="auth-submit" type="submit">${register?'Créer mon compte Studio':'Se connecter'}</button></form><p class="auth-explain">Les comptes Studio sont indépendants de la messagerie hushbun. pour le moment.</p></div></main>`;
 $('#authLogin').onclick=()=>authScreen('login');$('#authRegister').onclick=()=>authScreen('register');
 $('#authForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;const body=Object.fromEntries(new FormData(form));const r=await api(register?'/api/register':'/api/login',{method:'POST',body:JSON.stringify(body)});button.disabled=false;if(!r.ok){$('#authError').textContent=r.error||'Erreur de connexion';return}studioUser=r.user;await openMyStudio(true)};
}
async function hydrateCloudMedia(owner){cloudHydrating=true;try{
 const ids=portableMediaIds(profile);
 for(const id of ids){try{const r=await fetch('/api/media/'+encodeURIComponent(owner)+'/'+encodeURIComponent(id));if(!r.ok)continue;const blob=await r.blob();await mediaSet(id,new File([blob],id,{type:blob.type}));}catch(e){console.warn('Media load',id,e)}}
}finally{cloudHydrating=false}}
async function openMyStudio(edit=true){if(!studioUser)return authScreen();document.querySelector('#profileShareControls')?.remove();document.querySelector('.owner-edit')?.remove();publicViewCount=null;const result=await api('/api/my-profile');if(!result.ok)return authScreen('login',result.error);
 const old=result.profile||{};publicViewCount=Number.isFinite(Number(result.views))?Math.max(0,Number(result.views)):null;profile={...blankProfile(studioUser.username),...old,username:studioUser.username};publicProfileOwner=studioUser.username;
 await hydrateCloudMedia(studioUser.username);await loadMedia();await loadWidgetMedia();liveEditing=edit;entryDismissed=edit;history.replaceState({},'',edit?'/studio':profileUrl());renderPage();
}
async function openPublic(username){document.querySelector('#profileShareControls')?.remove();document.querySelector('.owner-edit')?.remove();const r=await api('/api/profile/'+encodeURIComponent(username));if(!r.ok){$('#app').innerHTML=`<main class="auth-page"><div class="auth-panel"><h1>Profil introuvable</h1><p>${safe(r.error||'Ce profil n’existe pas.')}</p><a href="/">Accueil hushbun. Studio</a></div></main>`;return}
 profile={...blankProfile(username),...r.profile,username};publicViewCount=Number.isFinite(Number(r.views))?Math.max(0,Number(r.views)):null;publicProfileOwner=username;await hydrateCloudMedia(username);await loadMedia();await loadWidgetMedia();liveEditing=false;entryDismissed=false;renderPage();
 document.querySelector('.owner-edit')?.remove();if(studioUser&&studioUser.username===username)installOwnerPublicActions();
}
async function copyMyPublicLink(){
 const url=location.origin+profileUrl();
 try{await navigator.clipboard.writeText(url);alert('Lien copié : '+url)}
 catch{prompt('Copie le lien de ton profil :',url)}
}
function installOwnerPublicActions(){
 if(!HOSTED||!studioUser||studioUser.username!==publicProfileOwner)return;
 document.querySelector('#profileShareControls')?.remove();
 const wrap=document.createElement('div');wrap.id='profileShareControls';wrap.className='profile-share-controls';
 wrap.innerHTML='<button type="button" id="sharePublicProfile">⧉ Copier le lien de mon profil</button>';
 document.body.append(wrap);
 wrap.querySelector('button').onclick=copyMyPublicLink;
}
function installAccountActions(){
 const panel=document.querySelector('.live-edit');if(!panel||!studioUser)return;
 document.querySelector('#studioAccountBar')?.remove();
 const wrap=document.createElement('div');wrap.id='studioAccountBar';wrap.className='studio-account-bar';
 wrap.innerHTML=`<span>@${safe(studioUser.username)}</span><button id="studioSignOut" type="button">Déconnexion</button>`;
 panel.append(wrap);
 wrap.querySelector('button').onclick=async()=>{await api('/api/logout',{method:'POST'});studioUser=null;publicProfileOwner=null;liveEditing=false;document.querySelector('.owner-edit')?.remove();document.querySelector('#profileShareControls')?.remove();authScreen('login')};
 const usernameInput=document.querySelector('[data-key="username"]');if(usernameInput){usernameInput.readOnly=true;usernameInput.title='Le pseudo public est lié à ton compte Studio.'}
}
async function bootHosted(){const me=await api('/api/me');if(me.ok&&me.user)studioUser=me.user;
 const path=decodeURIComponent(location.pathname);if(path==='/'||path==='/login'||path==='/register'){if(studioUser)await openMyStudio(true);else authScreen(path==='/register'?'register':'login');return}
 if(path==='/studio'||path==='/customize'){if(studioUser)await openMyStudio(true);else authScreen('login','Connecte-toi pour accéder à ton éditeur.');return}
 if(/^\/[a-z0-9_-]{3,24}$/i.test(path)){await openPublic(path.slice(1).toLowerCase());return}
 if(studioUser)await openMyStudio(true);else authScreen();
}
